css:
.qmarks { background:#ffefad; border:1.5px solid #dfb632; border-radius:8px; padding:1px 9px;
          font-size:14px; font-weight:700; white-space:nowrap; margin-left:6px;
          display:inline-block; }
.qhead .qmarks { font-size:13px; }
.eq-tail .qmarks { font-style:normal; }

/* The chip belongs TO the step above it. Given a line of its own it
   sat far right with a gap either side and read as an orphan; pulled
   up onto the equation's own baseline it reads as a note on it. */
.marksrow { text-align:right; margin:-14px 0 8px; line-height:1; }
.marksrow .qmarks { font-size:12.5px; padding:0 7px; }

.athsep { display:flex; align-items:center; gap:10px; margin:12px 0 6px; }
.athsep::before, .athsep::after { content:""; flex:1; height:1px;
          background:#d8d2c4; }
.athsep > span { font-family:'Kalam',cursive; font-size:16px; font-weight:700;
          color:#8a5a9e; letter-spacing:0.04em; white-space:nowrap; }

/* The chip belongs TO the step above it. Given a line of its own it
   sat far right with a gap either side and read as an orphan; pulled
   up onto the equation's own baseline it reads as a note on it. */
.marksrow { text-align:right; margin:-14px 0 8px; line-height:1; }
.marksrow .qmarks { font-size:12.5px; padding:0 7px; }

/* The `— स्रोत:` trailer closing a question. Folded into the head's chip
   when it names ONE paper; a question repeated across three or four papers
   keeps every code and stays a line of its own here. At `.q`'s 18.5px it
   read as another sentence of the question. */
.srccite { font-size:15.5px; line-height:1.5; color:#6b6656; margin:6px 0 2px; }
.srccite .ref { font-weight:700; }
